{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Our literature review aims to provide an overview of scientific research on the application of inclusive AI technologies in healthcare, highlighting their reported strengths, weaknesses, opportunities and threats. Our study was guided by the following research questions: ... What are the facets of inclusive AI, and what are the recommended strategies, solutions, and regulatory frameworks needed to realize inclusive AI technologies in healthcare? What are the application areas where inclusive AI technologies have been investigated? What are the potential benefits (strengths and benefits) of inclusive AI technologies within the healthcare domain? What are the potential challenges (weaknesses and threats) of inclusive AI technologies within the healthcare domain?",
      "reason": "The Introduction explicitly states the review aim and four research questions; the abstract (text_2) also states the objective. The questions are framed as research questions rather than a formal framework like PICO, but the objectives are explicitly stated."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "In this study, a literature review was adopted as the chosen research approach by carrying out a systematic review with conceptual synthesis, following the PRISMA 2020 guidelines",
      "reason": "This is a conceptual synthesis review of inclusive AI facets, benefits, and challenges, not a review of intervention effects, so planned PICO-style comparisons do not apply."
    }
  ],
  "confidence": 90
}

